package com.fireside.icons;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Arrays;
import javax.imageio.ImageIO;
import org.junit.Test;

public class PngEncoderTest
{
	private static final byte[] SIGNATURE = {(byte) 0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n'};

	/** Generated by our own code (no Jagex graphics), the size of an item sprite. */
	static BufferedImage testImage(int width, int height, int seed)
	{
		BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		for (int y = 4; y < height - 4; y++)
		{
			for (int x = 4; x < width - 4; x++)
			{
				int alpha = (x + y) % 3 == 0 ? 0x80 : 0xff;
				image.setRGB(x, y, alpha << 24 | (x * 7 + seed) % 256 << 16 | (y * 5) % 256 << 8 | seed % 256);
			}
		}
		return image;
	}

	@Test
	public void encodesAnItemSizedImageLosslessly() throws Exception
	{
		BufferedImage image = testImage(36, 32, 11);
		byte[] png = PngEncoder.encode(image);
		assertNotNull(png);
		assertArrayEquals(SIGNATURE, Arrays.copyOf(png, 8));
		assertTrue("too large: " + png.length, png.length <= PngEncoder.MAX_BYTES);

		BufferedImage decoded = ImageIO.read(new ByteArrayInputStream(png));
		assertEquals(36, decoded.getWidth());
		assertEquals(32, decoded.getHeight());
		for (int y = 0; y < 32; y++)
		{
			for (int x = 0; x < 36; x++)
			{
				int expected = image.getRGB(x, y);
				int actual = decoded.getRGB(x, y);
				if ((expected >>> 24) == 0)
				{
					assertEquals(0, actual >>> 24);
				}
				else
				{
					assertEquals("pixel " + x + "," + y, expected, actual);
				}
			}
		}
	}

	@Test
	public void skipsFullyTransparentImages()
	{
		// What a sprite that never loaded looks like.
		assertNull(PngEncoder.encode(new BufferedImage(36, 32, BufferedImage.TYPE_INT_ARGB)));
	}

	@Test
	public void skipsImagesTheServerWouldReject()
	{
		assertNull(PngEncoder.encode(testImage(65, 10, 1)));
		assertNull(PngEncoder.encode(testImage(10, 65, 1)));
		assertNotNull(PngEncoder.encode(testImage(64, 64, 1)));
	}
}
